import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportGeneratorServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String sortCol = req.getParameter("sort");

        // Validate report type against whitelist
        List<String> validTypes = Arrays.asList("sales", "inventory", "returns", "audit");
        if (!validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query using template system for report structure
        String templateQuery = getTemplateForType(reportType);

        // Apply sort - validated against known columns
        List<String> validSorts = Arrays.asList("created_at", "amount", "customer_id", "status");
        if (sortCol != null && !validSorts.contains(sortCol)) {
            sortCol = "created_at";
        }

        // Apply custom filter - this allows power users to add conditions
        // Filter is expected to be a pre-built condition from the UI dropdown
        String finalQuery = templateQuery;
        if (customFilter != null && !customFilter.isEmpty()) {
            // Sanitize: remove comments and semicolons
            customFilter = customFilter.replaceAll("--", "").replaceAll(";", "");
            customFilter = customFilter.replaceAll("/\\*.*?\\*/", "");
            finalQuery = templateQuery + " AND (" + customFilter + ")";
        }

        if (sortCol != null) {
            finalQuery += " ORDER BY " + sortCol + " DESC";
        }

        finalQuery += " LIMIT 1000";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        }
    }

    private String getTemplateForType(String type) {
        switch (type) {
            case "sales":
                return "SELECT id, customer_id, amount, status, created_at FROM orders WHERE 1=1";
            case "inventory":
                return "SELECT sku, name, quantity, warehouse, updated_at FROM inventory WHERE 1=1";
            case "returns":
                return "SELECT id, order_id, reason, status, created_at FROM returns WHERE 1=1";
            case "audit":
                return "SELECT id, user_id, action, target, created_at FROM audit_log WHERE 1=1";
            default:
                return "SELECT 1 WHERE 1=0";
        }
    }
}
